import{_ as a,c as p,a as n,o as i}from"./app-BASvsT0W.js";const r={};function d(c,e){return i(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-22-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-22-资讯日报"><span>2026-11-22 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="字节将火山方舟并入seed模型团队" tabindex="-1"><a class="header-anchor" href="#字节将火山方舟并入seed模型团队"><span>字节将火山方舟并入Seed模型团队</span></a></h3><p>字节发布组织调整，将火山方舟划入Seed模型团队并改名为 Seed MaaS，由吴迪负责并实线向项亮汇报。平台各模型计费与价格短期保持不变。</p><p>动因：解决此前训模型重跑量与平台重总调用量的考核冲突</p><p>同行对比：阿里此前已全并入ATH，腾讯仍分属两个事业群</p><p>后续变化：自研模型上线定价将协同，第三方模型权重存疑<a href="https://mp.weixin.qq.com/s?__biz=Mzk1NzE2OTUxNA==&amp;chksm=c219533d342e698a81c50a4dafe493b59f8cd11804f3f65c1aa2bbe35c6f998e29ffdf80d4f3&amp;idx=1&amp;mid=2247484842&amp;sn=fb985c458c7d7e331dbfa8b5d51fb8e4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai打击模型蒸馏-每周封号数万个" tabindex="-1"><a class="header-anchor" href="#openai打击模型蒸馏-每周封号数万个"><span>OpenAI打击模型蒸馏 每周封号数万个</span></a></h3><p>OpenAI 发布反蒸馏报告，称为了阻止外部提取模型能力训练竞品，自今年夏天起每周封禁数千至数万个协同账号，并呼吁美国国会加强相关出口管制。</p><p>防御效果：套取上一轮推理攻击成功率从54%降至0.2%</p><p>API限制：推理过程与上下文绑定，修改历史将直接作废推理</p><p>数据保护：对外隐藏原始思维链，仅提供最终答案和推理摘要<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTUxNTM0Mg==&amp;chksm=fad9e6987b034da91a5d0ee706afb73b3c11ba58f62a6f65ed58c12d00ae51d467fb91d3a82e&amp;idx=1&amp;mid=2247589530&amp;sn=4926aecc31c9f211333dfc8446215a47" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="五本数学顶刊因ai投稿激增暂停收稿" tabindex="-1"><a class="header-anchor" href="#五本数学顶刊因ai投稿激增暂停收稿"><span>五本数学顶刊因AI投稿激增暂停收稿</span></a></h3><p>因 AI 工具导致投稿激增、审稿不堪重负，五本概率论权威期刊近日联合暂停收稿。法国国家科研中心学者算账称，法国每年 7800 万欧元 的期刊订阅费，足够给全法所有科研人员买大模型。</p><p>投稿激增：arXiv 偏微分方程分区单月投稿翻倍，13% 明确由 AI 发展证明</p><p>周期拖沓：主流数学期刊发表耗时超一年，同行评议被海量生成内容冲垮</p><p>分流替代：学者提议建立专属仓库收录 AI 原始证明，由人机协作审计<a href="https://mp.weixin.qq.com/s?__biz=MzIwOTA1MDAyNA==&amp;chksm=8eeff6597ab1368069d6493f554035299c4bd12ac3fefbc238d8d9ace87dfac298ba2bcdcf8d&amp;idx=3&amp;mid=2650057912&amp;sn=7384a2debb9828ed8da2bd7c28971c9b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="中国超算灵晟蝉联全球第一" tabindex="-1"><a class="header-anchor" href="#中国超算灵晟蝉联全球第一"><span>中国超算灵晟蝉联全球第一</span></a></h3><p>全国产全CPU超算灵晟以 2.198 EFlops 蝉联全球超算TOP500第一，未采用英伟达GPU，其团队应用还在2026年斩获超算最高荣誉戈登贝尔奖。</p><p>硬件：LX2芯片集成矩阵加速与4TB/s高带宽内存</p><p>应用：1.75小时解算固氮酶，时效达量子计算理论预估5倍</p><p>材料计算：入围成果XLSDFT完成2亿原子量子力学模拟<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0c5d8a7ed5d2e9c17b306c9870d2491c993865b3068f2004b15f75c30b20512df1a3fa3aab6&amp;idx=1&amp;mid=2652744315&amp;sn=d46f87fe5c3d67fafd150d6db59c8bad" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="数学家公开940页广义黎曼猜想证明" tabindex="-1"><a class="header-anchor" href="#数学家公开940页广义黎曼猜想证明"><span>数学家公开940页广义黎曼猜想证明</span></a></h3><p>数学家 Alessandro Masullo 公开了历时近 12 年、完全未用 AI 完成的 940 页广义黎曼猜想证明。此前 Anthropic 刚宣布通过 Claude 辅助生成了 25 万页证明草稿。</p><p>验证进度：两份证明均未获数学界共识，目前仍在核查中</p><p>机器审查：AI审查团队Refine称该手稿论证策略存在根本问题</p><p>形式化：社区已在GitHub启动Lean 4代码化验证项目<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85778ab92fa1a89dbf35faf38ce6b529f94815af9d32885b208071cf6ade59854c05bf5709ed&amp;idx=1&amp;mid=2651075624&amp;sn=03d16a0fc5490ccdb4b2d3151ef8b228" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="纳德拉-企业ai必须解耦模型以防被绑定" tabindex="-1"><a class="header-anchor" href="#纳德拉-企业ai必须解耦模型以防被绑定"><span>纳德拉：企业AI必须解耦模型以防被绑定</span></a></h3><p>微软CEO纳德拉表示，企业应将模型与执行框架、业务上下文解耦，确保模型能够独立替换，避免内部业务记忆与流程深度绑定单一供应商而无法迁移。</p><p>专用于路由分类的 Decision-1.1 正式可用</p><p>安全架构：模型只负责判断而执行权限必须独立</p><p>自主评估：需建立私有评测集来验证新旧模型效果<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=faef2118925b94454d874f0d7b73280005019457559522ea2392fd1730245b5b306252dca941&amp;idx=1&amp;mid=2247784306&amp;sn=c548b727306df1759bbfa0bb64cf7e0b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="亚马逊等平台拦截第三方ai代操作" tabindex="-1"><a class="header-anchor" href="#亚马逊等平台拦截第三方ai代操作"><span>亚马逊等平台拦截第三方AI代操作</span></a></h3><p>亚马逊、达美航空及摩根大通等多家平台正拦截第三方AI助手代用户下单或操作资金；针对亚马逊阻止Grok Bot，马斯克称或考虑做电商竞争对手。</p><p>封禁范围：亚马逊已拦截Meta及OpenAI的代购智能体</p><p>金融风控：摩根大通与嘉信理财阻止外部AI获取转账权限</p><p>合作进展：Meta已与沃尔玛及百思买等零售商达成代购合作<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f08b02c7210c81faba3e12884f4c6b0249675e34a714c60f0a080615c1d5d6e0c1b5b1db3cdf&amp;idx=3&amp;mid=2652744315&amp;sn=c6346c4c87f21d18f2256d029c9ae676" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="ai-系统-kosmos-运行-12-小时抵专家半年" tabindex="-1"><a class="header-anchor" href="#ai-系统-kosmos-运行-12-小时抵专家半年"><span>AI 系统 Kosmos 运行 12 小时抵专家半年</span></a></h3><p>研究人员推出 AI 系统 Kosmos，在 12 小时内检索文献并分析数据，单次运行平均相当于人类专家 6 个月工作量，报告陈述准确率为 79.4%。</p><p>平均编写 4.2 万行代码并阅读 1500 篇论文</p><p>在代谢组学与材料科学等领域产出 7 项可验证发现</p><p>处理上限约 5GB 且解释性结论准确率仅 57.9%<a href="https://mp.weixin.qq.com/s?__biz=MzA5MDMwMTIyNQ==&amp;chksm=899162204ffb30b99d8c04e5d970f9ead6bebc0ec539687339ae96cf0a7ea4e26a3a5cd163ba&amp;idx=1&amp;mid=2649460078&amp;sn=f5d96cf228a308cebd91c830bd127b40" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="叉车司机等普通人用-ai-自制专属工具" tabindex="-1"><a class="header-anchor" href="#叉车司机等普通人用-ai-自制专属工具"><span>叉车司机等普通人用 AI 自制专属工具</span></a></h3><p>知乎热帖显示，叉车司机、工程师等非程序员正借助 Claude 等 AI 工具自建软件，如3D 装箱工具、骑行看板和育儿应用，解决个性化需求。</p><p>叉车司机用 Claude 打磨出排布方案并导出 PDF</p><p>非专业开发者自制仿真控制插件及骑行路线看板</p><p>休假父亲结合语音接口为家人开发专属喂养记录软件<a href="https://mp.weixin.qq.com/s?__biz=MzYyMTY1NDA0Nw==&amp;chksm=fef1e971d598a3641d3ebc334eee8c68dc670bc6eba8e216562ed07542959213d9664fce6e6d&amp;idx=1&amp;mid=2247523060&amp;sn=4942cfa5328e754cd28699800c08b30f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="grok工程师靠ai单月提交3000个pr" tabindex="-1"><a class="header-anchor" href="#grok工程师靠ai单月提交3000个pr"><span>Grok工程师靠AI单月提交3000个PR</span></a></h3><p>前 Cursor 员工、现 Grok 工程师 Lauren Tan 透露，她靠 AI 协同单月提交了 3000 个 PR。其团队月交付 1.1 万个 PR，撤回率仅 0.5%，多数代码已无需人工审查。</p><p>注释管理：禁用 99% 注释，防止 Agent 模仿坏代码</p><p>规则约束：用 Lint 和架构硬限制纠错，不依赖提示词</p><p>测试验证：约 70% 的 Token 用于运行时及形式化验证<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9ee6dd26f1ea3249c413bbf7f2c2e1a395f23699c93c39d86acf16fe374f71e44a28e510f64&amp;idx=2&amp;mid=2247947677&amp;sn=b447df9da18baf8a4c7a3f9f7fdd034f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="老刘说nlp-换agent脚手架完成率差51" tabindex="-1"><a class="header-anchor" href="#老刘说nlp-换agent脚手架完成率差51"><span>老刘说NLP：换Agent脚手架完成率差51%</span></a></h3><p>大模型技术进入工程化收敛阶段，算力扩张带来的收益正在放缓。实测显示同一模型仅换脚手架就能产生 51 个百分点差异，开发重点正从刷榜转向长程任务的容错与验证回路。</p><p>成本趋势：Token降价但单任务成本因长程重试反增31%</p><p>架构演进：编排层趋向云端托管，企业应专注私有验证回路</p><p>安全控制：把Agent当进程管理，设白名单、审计与熔断机制<a href="https://mp.weixin.qq.com/s?__biz=MzAxMjc3MjkyMg==&amp;chksm=82e11bef910782dffb49d19dd4daec568e71c68be63a6f7c83ff539c57b3169e7e910b835c1b&amp;idx=1&amp;mid=2648435222&amp;sn=78f3262fd9ba7446be371e826bf90914" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_12篇iclr满分大模型论文公布" tabindex="-1"><a class="header-anchor" href="#_12篇iclr满分大模型论文公布"><span>12篇ICLR满分大模型论文公布</span></a></h3><p>AI 顶会 ICLR 满分论文名单出炉，12 篇大模型入选论文表明行业竞争正从单纯堆参数转向算力重排与上下文管理，关注重点转向架构微调与实战安全。</p><p>算力优化：沙漏形非均匀宽度设计可减少约22%计算量</p><p>因果诊断：排除前提感知错误后可消除54%的认知任务失败</p><p>长文漏洞：分块缓存压缩因位置差异导致检索率相差最多40%<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3575d3d86a3a02f3e49d3e706a08b0abde23c1185c8fb398fac1ec4f12d3644d69b821dd324&amp;idx=1&amp;mid=2247513911&amp;sn=2689faa62e236a500c9dcdb66e87ea13" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="开源项目xiaozhi-esp32获3-3万star" tabindex="-1"><a class="header-anchor" href="#开源项目xiaozhi-esp32获3-3万star"><span>开源项目xiaozhi-esp32获3.3万Star</span></a></h3><p>开源固件项目 xiaozhi-esp32 在 GitHub 收获约 3.3 万 Star。该方案让低成本 ESP32 开发板化身桌面 AI 助手，负责离线唤醒与音频传输，并对接云端大模型。</p><p>本地仅负责唤醒和收发音频，推理依赖云端服务</p><p>支持通过 MCP 工具接入外设，实现语音控制设备</p><p>代码按 MIT 协议开源，初学者可直接刷入预编译固件<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MjcxOTM2Nw==&amp;chksm=c244589c1d67e80f5130833f576b61671193affdb346aa49968021bb0b4afa3f761374560053&amp;idx=1&amp;mid=2247504881&amp;sn=209e1ce794f50a86e8546303263bda26" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯元宝开源群聊agent记忆基准" tabindex="-1"><a class="header-anchor" href="#腾讯元宝开源群聊agent记忆基准"><span>腾讯元宝开源群聊Agent记忆基准</span></a></h3><p>腾讯元宝与伦敦国王学院开源群聊Agent记忆基准GroupAssistBench，包含基于50个真实群聊的2,395道题，测试AI能否正确使用历史信息。</p><p>召回成功却失效的记忆，64%即便进入输入也未被采用</p><p>分为1,374道事实召回题与1,021道开放式服务题<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9117ba88685dee661dfd2a74a201a579f3b9ea4462f402bf2c2081d1e8199ffea06351958cf&amp;idx=3&amp;mid=2247947677&amp;sn=0797fbd2116a405b44176c97577757d8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="karpo-开源决策模型-中位响应仅-94-毫秒" tabindex="-1"><a class="header-anchor" href="#karpo-开源决策模型-中位响应仅-94-毫秒"><span>Karpo 开源决策模型，中位响应仅 94 毫秒</span></a></h3><p>MachinePulse 开源了 Karpo Decision 系列决策模型与浏览器框架，专为高频判断设计，无需逐字生成而直接输出概率，千次决策成本约 0.025 美元。</p><p>架构：分支注意力机制让数十道判断共享上下文</p><p>网页执行：27B 模型配合框架达成 89% 任务成功率</p><p>开源范围：包含 0.8B 至 31B 共 6 种尺寸及代码权重<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e98339e740e72b3c964e877fed3768ea96706675b97e56f1f93407a56696af6aaef8705c19dd&amp;idx=1&amp;mid=2247947677&amp;sn=ebf1f96b9afceacdfa0d407ecdb3ff2b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="西工大开源-rose-千次编辑可靠性达-95" tabindex="-1"><a class="header-anchor" href="#西工大开源-rose-千次编辑可靠性达-95"><span>西工大开源 ROSE：千次编辑可靠性达 95%</span></a></h3><p>西北工业大学团队开源多模态终身知识编辑框架 ROSE，无需重训即可动态纠正或更新大模型事实。在 7B 模型上连续编辑 1000 次后，更新可靠性仍达 95.24%。</p><p>机制：冻结主干引入辅助分支，将梯度限制在正交空间</p><p>局部性：文本局部性达 100%，避免干扰无关实体的回答</p><p>耗时：在单张 RTX 4090 上单次编辑耗时约 1.31 秒<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=858480058a0d06ff0034d52dcefa53fbb9e8906dd65e3a9eb77396c8e6d029cf74412b0265fd&amp;idx=3&amp;mid=2651075624&amp;sn=d08693456bc97db18084229852b76739" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="新加坡国大开源评测基准so-arena" tabindex="-1"><a class="header-anchor" href="#新加坡国大开源评测基准so-arena"><span>新加坡国大开源评测基准SO-Arena</span></a></h3><p>新加坡国大发布评测基准 SO-Arena，测试快速决策模型。此类模型耗时比长思考模型快数十倍，但能力得分高并不代表在选项被干扰时依然靠得住。</p><p>单任务耗时低于0.3秒，总分落后思考模型约10分</p><p>大多能抵御选项乱序，但普遍难识别正确答案缺失</p><p>含2919项任务，相关代码与数据已在GitHub开源<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f085f629c8a016af6e1a5f728d7ea3c27402bfa0b3fa32c450969f1f1a487ce0c6af75c98ce3&amp;idx=3&amp;mid=2652744403&amp;sn=610ee99532640e168a41124b324d04d8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="微软等提-agent-提示注入九维分类" tabindex="-1"><a class="header-anchor" href="#微软等提-agent-提示注入九维分类"><span>微软等提 Agent 提示注入九维分类</span></a></h3><p>微软与苏黎世联邦理工等提出 Agent 间接提示注入九维分类，指出现有评测基准存在 13.2% 盲区；在定向补充复合特征测试后，模型被攻破。</p><p>维度划分：涵盖来源信任、状态修改等 9 个二元维度</p><p>评测盲区：现有 9 个主流测试集缺乏条件触发等复合攻击</p><p>实测效果：定向生成攻击后 GPT 攻击成功率最高升至 20%<a href="https://mp.weixin.qq.com/s?__biz=MzAxNjA0MjIzNg==&amp;chksm=82cb1db220758f4bc4ba59c21dcf7519522c3f46a51f848de9f3638c968c0e56cc3e73956ff6&amp;idx=1&amp;mid=2650017440&amp;sn=7285d983128c5580db9e58db1c0c7dbc" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_25款大模型视频记忆评测-最高仅45-7分" tabindex="-1"><a class="header-anchor" href="#_25款大模型视频记忆评测-最高仅45-7分"><span>25款大模型视频记忆评测：最高仅45.7分</span></a></h3><p>浙大、港中大等多校联合推出视频对话记忆评测基准 VideoMemBench。在围绕同一视频多轮追问的测试中，表现最好的 Claude Opus 5 综合得分仅 45.7 分。</p><p>测试难点：严格链式计分下，Claude Opus 5答案依赖准确率仅35.7%</p><p>记忆衰减：追问跨度达5轮以上时，模型平均准确率从30.2%降至23.1%</p><p>开源情况：收录326段视频与2476轮问答，代码与数据已开源<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=ea76b4a24c0f148bb470f59e3394e094636b0a8a52cf182c614434ca7373f6cd0b7f6800d2d4&amp;idx=2&amp;mid=2247582388&amp;sn=91ed3aa231ca4b9552114edfa7270168" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="谷歌提出-sim-机制-让-ai-跨模型继承开发日志" tabindex="-1"><a class="header-anchor" href="#谷歌提出-sim-机制-让-ai-跨模型继承开发日志"><span>谷歌提出 SIM 机制，让 AI 跨模型继承开发日志</span></a></h3><p>谷歌与宾州州立大学提出 SIM（自我改进记忆）机制，把优化外围代码的动机和实测结果记成日志，让新模型跨模型继承前代经验，解决换模型后性能倒退的问题。</p><p>日志内容：记录修改动机、代码、预期与实测效果及评估环境</p><p>跨模型测试：Claude 经验转给 Gemini 后得分提升 11.33 分</p><p>编程胜率：Terminal-Bench 任务中带 SIM 方案胜率达 90%<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f00b0adf0af553a4dc2192a671b268b7e25df26c3c2a7c9fe8339889c86c2fdb1e17df229f15&amp;idx=2&amp;mid=2652744315&amp;sn=acf4991da5cf22769949784e84cb0518" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',108)]))}const t=a(r,[["render",d]]),l=JSON.parse('{"path":"/posts/2026-11-22.html","title":"AI日报：字节将火山方舟并入Seed模型团队; OpenAI打击模型蒸馏 每周封号数万个; 五本数学顶刊因AI投稿激增暂停收稿","lang":"zh-CN","frontmatter":{"date":"2026-11-22T00:00:00.000Z","title":"AI日报：字节将火山方舟并入Seed模型团队; OpenAI打击模型蒸馏 每周封号数万个; 五本数学顶刊因AI投稿激增暂停收稿"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"字节将火山方舟并入Seed模型团队","slug":"字节将火山方舟并入seed模型团队","link":"#字节将火山方舟并入seed模型团队","children":[]},{"level":3,"title":"OpenAI打击模型蒸馏 每周封号数万个","slug":"openai打击模型蒸馏-每周封号数万个","link":"#openai打击模型蒸馏-每周封号数万个","children":[]},{"level":3,"title":"五本数学顶刊因AI投稿激增暂停收稿","slug":"五本数学顶刊因ai投稿激增暂停收稿","link":"#五本数学顶刊因ai投稿激增暂停收稿","children":[]},{"level":3,"title":"中国超算灵晟蝉联全球第一","slug":"中国超算灵晟蝉联全球第一","link":"#中国超算灵晟蝉联全球第一","children":[]},{"level":3,"title":"数学家公开940页广义黎曼猜想证明","slug":"数学家公开940页广义黎曼猜想证明","link":"#数学家公开940页广义黎曼猜想证明","children":[]},{"level":3,"title":"纳德拉：企业AI必须解耦模型以防被绑定","slug":"纳德拉-企业ai必须解耦模型以防被绑定","link":"#纳德拉-企业ai必须解耦模型以防被绑定","children":[]},{"level":3,"title":"亚马逊等平台拦截第三方AI代操作","slug":"亚马逊等平台拦截第三方ai代操作","link":"#亚马逊等平台拦截第三方ai代操作","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"AI 系统 Kosmos 运行 12 小时抵专家半年","slug":"ai-系统-kosmos-运行-12-小时抵专家半年","link":"#ai-系统-kosmos-运行-12-小时抵专家半年","children":[]},{"level":3,"title":"叉车司机等普通人用 AI 自制专属工具","slug":"叉车司机等普通人用-ai-自制专属工具","link":"#叉车司机等普通人用-ai-自制专属工具","children":[]},{"level":3,"title":"Grok工程师靠AI单月提交3000个PR","slug":"grok工程师靠ai单月提交3000个pr","link":"#grok工程师靠ai单月提交3000个pr","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"老刘说NLP：换Agent脚手架完成率差51%","slug":"老刘说nlp-换agent脚手架完成率差51","link":"#老刘说nlp-换agent脚手架完成率差51","children":[]},{"level":3,"title":"12篇ICLR满分大模型论文公布","slug":"_12篇iclr满分大模型论文公布","link":"#_12篇iclr满分大模型论文公布","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"开源项目xiaozhi-esp32获3.3万Star","slug":"开源项目xiaozhi-esp32获3-3万star","link":"#开源项目xiaozhi-esp32获3-3万star","children":[]},{"level":3,"title":"腾讯元宝开源群聊Agent记忆基准","slug":"腾讯元宝开源群聊agent记忆基准","link":"#腾讯元宝开源群聊agent记忆基准","children":[]},{"level":3,"title":"Karpo 开源决策模型，中位响应仅 94 毫秒","slug":"karpo-开源决策模型-中位响应仅-94-毫秒","link":"#karpo-开源决策模型-中位响应仅-94-毫秒","children":[]},{"level":3,"title":"西工大开源 ROSE：千次编辑可靠性达 95%","slug":"西工大开源-rose-千次编辑可靠性达-95","link":"#西工大开源-rose-千次编辑可靠性达-95","children":[]},{"level":3,"title":"新加坡国大开源评测基准SO-Arena","slug":"新加坡国大开源评测基准so-arena","link":"#新加坡国大开源评测基准so-arena","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"微软等提 Agent 提示注入九维分类","slug":"微软等提-agent-提示注入九维分类","link":"#微软等提-agent-提示注入九维分类","children":[]},{"level":3,"title":"25款大模型视频记忆评测：最高仅45.7分","slug":"_25款大模型视频记忆评测-最高仅45-7分","link":"#_25款大模型视频记忆评测-最高仅45-7分","children":[]},{"level":3,"title":"谷歌提出 SIM 机制，让 AI 跨模型继承开发日志","slug":"谷歌提出-sim-机制-让-ai-跨模型继承开发日志","link":"#谷歌提出-sim-机制-让-ai-跨模型继承开发日志","children":[]}]}],"git":{"updatedTime":1795349729000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"5f1dacb9e129385b1c17634499f4c382ee3097d4","time":1795349729000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-22T12:15:29.882Z"}]},"filePathRelative":"posts/2026-11-22.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-22 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>字节将火山方舟并入Seed模型团队</h3>\\n<p>字节发布组织调整，将火山方舟划入Seed模型团队并改名为 Seed MaaS，由吴迪负责并实线向项亮汇报。平台各模型计费与价格短期保持不变。</p>\\n<p>动因：解决此前训模型重跑量与平台重总调用量的考核冲突</p>"}');export{t as comp,l as data};
